entries[273071] = { ["name"] = "Enchant Weapon - Rite of the Hash'ey", ["text"] = "Use: Permanently enchants a weapon with Rite of the Hash'ey, causing your spells and abilities to grant you Hash'ey's Might, granting you 120 of a random secondary stat for 15 sec and favors your highest secondary stat when you're above 80% health. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\nSell Price:" }
entries[273072] = { ["name"] = "Enchant Weapon - Rite of the Hash'ey", ["text"] = "Use: Permanently enchants a weapon with Rite of the Hash'ey, causing your spells and abilities to grant you Hash'ey's Might, granting you 139 of a random secondary stat for 15 sec and favors your highest secondary stat when you're above 80% health. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\nSell Price:" }
entries[273073] = { ["name"] = "Formula: Rite of the Hash'ey", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Rite of the Hash'ey.\n\nPermanently enchants a weapon with Rite of the Hash'ey, causing your spells and abilities to grant you Hash'ey's Might, granting you 80 of a random secondary stat for 15 sec and favors your highest secondary stat when you're above 80% health. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\nRequires Midnight Enchanting (50)\nRequires Renown Rank 5 with Zul'jarra's Forces." }
