entries[273794] = { ["name"] = "Knot of Writhing Serpents", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 Intellect\nEquip: Your harmful spells have a chance to ensorcell a serpent into spewing venom at your target, inflicting ( 5352 * 1 ) Nature damage split between nearby enemies. Damage increased by 30% per additional enemy, up to 150%.\n\nThe primary target also suffers an additional ( 5352 * 1 ) Nature damage over 15 sec.\nSell Price:" }
entries[273795] = { ["name"] = "Coiled Fangstone", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 Strength\nUse: Unleash 3 Envenomed Bites centered on your target, inflicting a total of [source value]) Nature damage split between nearby enemies. Damage increased by 30% per additional enemy, up to 150%. (1 Min Cooldown)\nSell Price:", ["unresolvedValues"] = true }
entries[273796] = { ["name"] = "Vile Vial of Volatile Venom", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 [Agility or Strength or Intellect]\nUse: Take a small sip of venom, gaining 514 of a random secondary stat for 15 sec. Afterwards, a random secondary stat is reduced by 73 for 15 sec. (2 Min Cooldown)\n\"Questionable? Yes. Potable?... Technically yes.\"\nSell Price:" }
entries[273797] = { ["name"] = "Tattered Amani War Banner", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 [Agility or Strength]\nUse: Plant the banner for 15 sec! Fighting within 12 yards of it fills you with Battle Fervor, granting 306 of your highest secondary stat. Defeating at least 1 enemy while the banner stands will extend Banner's duration by 5 sec. (1 Min, 30 Sec Cooldown)\n\"Aged and worn, it has led the Amani to countless victories in ages past.\"\nSell Price:" }
