entries[274164] = { ["name"] = "Hearthkeeper's Wandering Caravan", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Comfortable as your own home and adventurous as a tortollan trader, the Hearthkeeper's Wandering Caravan will carry you in luxurious style anywhere your travels on Azeroth take you.\"\nIn-Game Shop" }
entries[274260] = { ["name"] = "Rabbit'ath", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The presence of Rabbit'ath brings doom and despair to all who witness. Legend says that in its eyes, you can glimpse the end of all things.\"\nPromotion:\nBlizzCon 2026" }
