entries[274476] = { ["name"] = "Spark of Tides", ["text"] = "Midnight Season 2\nBinds when picked up\nOptional Crafting Reagent\n\n\"A unique crafting material imbued with cerulean water. Obtained through weekly quests or end-game activities, it is used to create the most powerful of equipment via professions.\"\nSell Price:" }
