entries[274493] = { ["name"] = "Effigy of Ula'tek's Faithful", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+50 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to grant you 179 of a random secondary stat and 89 of a random tertiary stat for 12 sec.\nSell Price:" }
entries[274494] = { ["name"] = "Chiral Marrowgrafter", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 63 Mastery\nUse: Heal a target ally for 94406 . Any overhealing passes to the next most injured party member until all healing has been applied. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[274495] = { ["name"] = "Pulse Seeker's Oculus", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+50 Intellect\nEquip: Your Mastery is increased by 46 , plus an additional 10 while a party member is below 65% health.\nIf a party member's health drops below 35%, the oculus dilates, increasing these effects by 100% for 12 sec. This can only occur every 5 min.\nSell Price:" }
entries[274496] = { ["name"] = "Ophidian Bone Whistle", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 63 Critical Strike\nUse: Send a spirit snake to your target's location, dealing ( 62900 * 1 ) Nature damage split among nearby enemies. When this ability finishes cooling down, your next harmful spell or ability will send another spirit snake. (3 Min Cooldown)\nSell Price:" }
entries[274497] = { ["name"] = "Spirit-Rending Poison", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 63 Haste\nUse: Fire a poison volley, applying 5 stacks of Spirit-Rending Poison split among nearby enemies. Each application deals ( 2013 * 30 / 2) Nature damage over 30 sec.\nIf an afflicted target dies the Venom is expelled, instantly dealing its remaining damage split between nearby enemies. (3 Min Cooldown)\nSell Price:" }
entries[274498] = { ["name"] = "Spirit Ward", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 63 Versatility\nUse: Apply the Ward to yourself for 20 sec, absorbing 25% of damage taken until 163171 damage has been prevented.\nWhile below 50% health, absorbs 75% of damage taken instead. (2 Min Cooldown)\nSell Price:" }
entries[274499] = { ["name"] = "Toxiferous Transfusion", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+50 [Agility or Strength]\nEquip: Taking damage has a high chance to cause you to spew venomous bile, dealing 1196 Nature damage split among nearby enemies. You then reabsorb the bile, gaining 43 Leech per affected enemy, up to ( 43 * 5), for 8 sec.\nSell Price:" }
entries[274500] = { ["name"] = "Demystifyin': Alchemy", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Midnight Alchemy Knowledge by 10.\nRequires Midnight Alchemy (25)\nRequires Renown Rank 6 with Zul'jarra's Forces.\n\"An article depicting all the ways artisan crafters improve their skills.\"" }
