entries[274587] = { ["name"] = "Spotted Killifish", ["text"] = "Use: Throw the catch back into the water to gain 25 Midnight Perception for 30 sec.\n\nThrowing multiple catches can extend this buff up to 5 min.\nCrafting Reagent\n\"A common fish from the Coiled Isle. Can be bought and sold on the Auction House.\"\nSell Price:" }
