entries[274640] = { ["name"] = "Arcfluxion Hydrospore", ["text"] = "Quest Item\nUnique\n\"A pure, living ley-spore fused with the arcane-rich waters of Naigtal pulses within the containment sphere.\"" }
entries[274649] = { ["name"] = "Voidmancer's Starcarver", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses the Voidmancer's Starcarver. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires the completion of the A Trip Around the Stars Achievement.\n\n\"This pinnacle of Voidmancer transport technology was once a symbol of status and power among high ranking domanaar. After its creator mysteriously vanished, it was viewed as unseemly when used on core worlds gatherings.\"\nAchievement:\nA Trip Around the Stars\nZone:\nVal\nVendor:\nKifaan\nCost:\n15" }
entries[274650] = { ["name"] = "Netherforged Nullframe", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses the Netherforged Nullframe. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires the completion of the A Trip Through the Stars Achievement.\n\n\"Assembled by the Lightforged, sundered by the Hal'hadar, and restored by a Technomancer. A matrix of light, void, and arcane swirls within this renewed Warframe.\"\nAchievement:\nA Trip Through the Stars\nZone:\nNaigtal\nVendor:\nKifaan\nCost:\n15" }
