entries[274681] = { ["name"] = "Badlands Buzzard", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The white buzzards are some of the rarest in all the Badlands. Rumor has it that one may even be caught and tamed to fight alongside hunters.\"\nTrading Post" }
entries[274682] = { ["name"] = "Tetla'ketl's Conjuring Crest", ["text"] = "Quest Item\nUnique\n\"Used in the conjurer's ritual. The plumage still glows.\"" }
