entries[274705] = { ["name"] = "Ruma's Infestation Eradicator", ["text"] = "Quest Item\nUnique\nUse: Use on Medic La'una to eradicate the writhing infestation inside of her. (5 Sec Cooldown)" }
entries[274707] = { ["name"] = "Crystallized Venomblight Manaflux", ["text"] = "Binds when picked up\n\"Grant Venomblight Manaflux capable of imbuing armor with incredible power at the Catalyst in Silvermoon.\"\n<Right Click to Open>" }
entries[274708] = { ["name"] = "Nebulous Voidcache: Nymrissa Wavecaller", ["text"] = "Binds when picked up\n\"Transmute a Nebulous Voidcore into a piece of equipment for your Loot Specialization.Items may be received once per difficulty level until all potential items for your current specialization have been transmuted.\"\n<Right Click to Open>" }
