entries[274763] = { ["name"] = "Fleeting Liquid Luster", ["text"] = "Conjured Item\nUnique: Fleeting Potion (20)\nUse: Drink to apply Lustrous Gleam every 6 seconds for 30 sec seconds, increasing your Versatility by 358 while this potion is active.\n\nApplications of Lustrous Gleam stack up to 5 times." }
entries[274764] = { ["name"] = "Fleeting Liquid Luster", ["text"] = "Conjured Item\nUnique: Fleeting Potion (20)\nUse: Drink to apply Lustrous Gleam every 6 seconds for 30 sec seconds, increasing your Versatility by 420 while this potion is active.\n\nApplications of Lustrous Gleam stack up to 5 times." }
entries[274765] = { ["name"] = "Fleeting Alluring Nostrum", ["text"] = "Conjured Item\nUnique: Fleeting Potion (20)\nUse: Accept the Void's gifts, empowering your damaging spells and abilities a chance to deal 12565 Shadow damage to your current target and up to 4 nearby enemies for 30 sec.\n\nThe Void's boons will burden you, slowing your movement speed by 15%, stacking up to 5 times." }
entries[274766] = { ["name"] = "Fleeting Alluring Nostrum", ["text"] = "Conjured Item\nUnique: Fleeting Potion (20)\nUse: Accept the Void's gifts, empowering your damaging spells and abilities a chance to deal 10724 Shadow damage to your current target and up to 4 nearby enemies for 30 sec.\n\nThe Void's boons will burden you, slowing your movement speed by 15%, stacking up to 5 times." }
entries[274767] = { ["name"] = "Seaside Lounge Chair", ["text"] = "3\nSeaside Lounge Chair\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest." }
entries[274772] = { ["name"] = "Ethereal Bandage", ["text"] = "Use: Heals 8% of your health and removes one infusion every sec for 6 sec.\n\nOnly effective on Val and Naigtal.\nSell Price:" }
entries[274774] = { ["name"] = "Frost-Injected Vapor", ["text"] = "Use: You become immune to being frozen and deflect 25% of Frost damage done to you back at the attacker for 1 hour.\n\nYou can only have one vapor active at a time in Naigtal or Val.\nSell Price:" }
entries[274775] = { ["name"] = "Void Hungerer's Vapor", ["text"] = "Use: Your stare increases the cast time of spells that creatures in front of you cast by 50% for 1 hour. Additionally, Cosmic Horror can no longer affect you.\n\nVoid Hungerer's Vapor Cosmic Horror :\nInstills madness in players who look toward it, inflicting 20 Shadow damage and causing them to cower in fear for 6 sec.\n\nYou can only have one vapor active at a time in Naigtal or Val.\nSell Price:" }
entries[274777] = { ["name"] = "Neutralized Venom Clot", ["text"] = "Crafting Reagent\n\"This is all that remains after neutralizing venom on the Coiled Isle. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[274780] = { ["name"] = "Fungal Spore Vapor", ["text"] = "Use: [NYI] Slaying a fungal creature causes nearby Mushrooms, Sleeping Gas, Spores, and Vines to wither away for 1 hour.\n\nYou can only have one vapor active at a time in Naigtal or Val.\nSell Price:" }
entries[274781] = { ["name"] = "Cursebound Globe", ["text"] = "Crafting Reagent\n\"The object thrums with unsettling energy. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[274782] = { ["name"] = "Tether-Severing Vapor", ["text"] = "Use: You deal 50% more damage to summoned creatures for 1 hour. When slain, their summoner takes Arcane damage equal to their max health.\n\nYou can only have one vapor active at a time in Naigtal or Val.\nSell Price:" }
entries[274783] = { ["name"] = "Fel Embers", ["text"] = "Quest Item\nRequires level 80 to 90 ( 90)\n\"Still warm to the touch.\"" }
