entries[275440] = { ["name"] = "Cerulean Deathwalker", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nYou don't have a Timelost Saddle. You cannot purchase this item.\n\n\"A frozen tide of wailing souls, locked in cerulean ice, grinds onward under the weight of eternal suffering.\"\nVendor:\nLindormi" }
entries[275442] = { ["name"] = "Amethyst Mechsuit", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nYou don't have a Timelost Saddle. You cannot purchase this item.\n\n\"Where diamond reflects perfection, amethyst resonates with power.\"\nVendor:\nLindormi" }
