entries[275631] = { ["name"] = "Corrosive Writhling", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\n\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nSell Price:" }
entries[275632] = { ["name"] = "Volatile Venomfang", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\n\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nSell Price:" }
entries[275634] = { ["name"] = "Artisan's Consortium Flyer", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A notice promoting a special giveaway in Falconwing Square.\"" }
entries[275652] = { ["name"] = "Crimson Venomfang", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A venomfang's most deadly weapon is its terrifying tail, which can mortally envenom its prey with a mere scratch.\"\nAchievement:\nGlory of the Venomous Abyss Raider\nCategory:\nDungeons & Raids" }
entries[275653] = { ["name"] = "Sea-Dwelling Isle Serpent", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Bloodsworn Crew or above with Captain Tokka's Crew.\n\n\"This oozing serpent has a taste for fish. As long as you can feed them, they should remain friendly. Should.\"\nVendor:\nSecond Mate Sluggs\nZone:\nThe Coiled Isle" }
entries[275654] = { ["name"] = "Caustic Venomfang", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This venomfang's toxins are potent enough to liquidate its prey in seconds.\"\nVendor:\nSkull of Er'inye\nZone:\nVaults of Atal'Utek\nCost:\n10000" }
entries[275655] = { ["name"] = "Venom Serpent - White", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding" }
entries[275656] = { ["name"] = "Auriferous Venomfang", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Its stealth foiled by bright scales, this venomfang lurks among hidden treasure for the next meal.\"\nAchievement:\nTreasures of the Coiled Isle\nCategory:\nMidnight" }
entries[275657] = { ["name"] = "Apophic Soul Crusher", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Once powered by the arcane, now fueled solely by the tortured spirits of the unfaithful.\"\nAchievement:\nLet Me Solo Him: Azta'rec" }
entries[275658] = { ["name"] = "Primeval Skyfriend", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The most vicious elder skyfiends lurk within the confines of the Venomous Abyss, surfacing only to stalk prey across the shores of Atal'Utek before returning to their fetid lairs. This one has become your sky-friend.\"\nDrop:\nThe Venomous Abyss\nLocation:\nUla'tek (Mythic)" }
entries[275659] = { ["name"] = "Hexflame Reaver", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Its glow is a warning: the hunt is already over.\"\nDrop:\nRal'kala" }
entries[275660] = { ["name"] = "Preyhunter's Fury", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Preyhunter's Journey rank 10.\n\n\"You don't follow tracks; you follow the fading green fire.\"\nVendor:\nConstruct V'anore\nZone:\nSilvermoon City\nCost:\n2250" }
entries[275662] = { ["name"] = "Frosticus Maximus", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\n\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nRequires the completion of the Ultradon Carnage achievement on Val.\nSell Price:" }
entries[275663] = { ["name"] = "Silento", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\n\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nRequires the completion of the Showdown Success achievements for both Val and Naigtal.\nSell Price:" }
entries[275664] = { ["name"] = "Tortured Gorger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires the completion of the Heroic Showdowns Achievement.\n\n\"Both domanaar and ethereals have tried to cage this devourer. Each time they have failed. Now, soaked in the energies of the void, this tormented gorger is ready to unleash havoc.\"\nZones:\nVal and Naigtal\nAchievement:\nHeroic Showdowns\nVendor:\nKifaan\nCost:\n15" }
entries[275665] = { ["name"] = "Phase-Displaced Toy", ["text"] = "Binds when picked up\nUnique\n\"A favorite of the purrkin on K'aresh.\"\nSell Price:" }
entries[275667] = { ["name"] = "Veilcaster", ["text"] = "Quest Item\nUse: Disguise self as a domanaar, allowing for safe passage unless detected by other domanaars. (3 Sec Cooldown)" }
entries[275670] = { ["name"] = "Bill of Lading", ["text"] = "Unique\n<Right Click to Read>" }
entries[275676] = { ["name"] = "R0CKY-To-Go", ["text"] = "Use: Reduces your falling speed for 2 min.\nSell Price:" }
entries[275683] = { ["name"] = "G-00", ["text"] = "Toy\nUse: Empower this harmless bot with embedded Neutralized Venom Clots, collecting loot from corpses within 40 yds and melting them into pools of venomous goo. (3 Sec Cooldown)\nRequires Midnight Engineering (1)\nSell Price:" }
entries[275684] = { ["name"] = "Schematic: G-00", ["text"] = "Binds to Warband\nUse: Teaches you how to craft G-00.\nRequires Midnight Engineering (50)" }
entries[275686] = { ["name"] = "Decrypted Intel Sphere", ["text"] = "Quest Item\n\"A flurry of projected images, alien letters, and other information churns within the energy sphere.\"" }
entries[275687] = { ["name"] = "Soul Lattice Holoprint", ["text"] = "Quest Item\n\"Shimmering runes and 3D projections of something called a \"Soul Lattice\" flickers across the holoprint.\"" }
entries[275689] = { ["name"] = "Glittering Crypt Holoprint", ["text"] = "Quest Item\n\"A flickering 3D overlay of a non-ethereal structure shimmers across the holoprint.\"" }
entries[275690] = { ["name"] = "Riftstalker's Cache", ["text"] = "Binds when picked up\n\"Cache containing Field Accolades, Relic Coffer Key shards, materials for upgrading gear, gold, and more.\"\n<Right Click to Open>" }
entries[275691] = { ["name"] = "Riftstalker's Overflowing Cache", ["text"] = "Binds when picked up\n\"Cache containing Field Accolades, Relic Coffer Key shards, materials for upgrading gear, gold, and more. Will contain items from the Riftstalker's Cache if not already claimed.\"\n<Right Click to Open>" }
entries[275693] = { ["name"] = "Design: Opalescent Amani Peridot", ["text"] = "Binds when picked up\nUse: Teaches you how to craft an Opalescent Amani Peridot.\nRequires Midnight Jewelcrafting (50)\nRequires Cursed Angler or above with Captain Tokka's Crew." }
entries[275695] = { ["name"] = "Design: Piercing Amani Lapis", ["text"] = "Binds to Warband\nUse: Teaches you how to craft a Piercing Amani Lapis.\nRequires Midnight Jewelcrafting (50)" }
