entries[275707] = { ["name"] = "Miasmic Jewelbinder", ["text"] = "Binds when picked up\nUse: Add a socket to a Midnight Season 2 item that does not already have one. Can be used on Helms, Bracers, or Belts. Cannot be used on PvP equipment." }
entries[275726] = { ["name"] = "Preyhunter's Champion Chest", ["text"] = "Binds when picked up\n\"A chest containing a piece of Champion equipment, supplies, gold, and a chance for professions materials. Your first four Preyhunter's containers awarded by hunts a week also have a chance to include Corrosive Souls.\"\n<Right Click to Open>" }
