entries[275825] = { ["name"] = "Ula'tek's Sssacrificial Rain", ["text"] = "Binds when picked up\nToy\nUse: The sssky opens! Each slain enemy player feeds the endless belly, their form melting into a pool fit for the brood. Lasts 30 min. (30 Min Cooldown)" }
